// The skeleton of the app was generated by claude 
// Some clean up was done by claude as well

import express, {
  type NextFunction,
  type Request,
  type Response,
} from "express";
import cors from "cors";
import { randomUUID } from "node:crypto";

const app = express();

const LOCAL_ORIGIN = /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/;

app.use(
  cors({
    origin(origin, callback) {
      callback(null, !origin || LOCAL_ORIGIN.test(origin));
    },
  }),
);
app.use(express.json());
app.use((_req, res, next) => {
  res.set("Cache-Control", "no-store");
  next();
});

const PORT = Number(process.env.PORT) || 3000;
const SESSION_TTL_MS = Number(process.env.SESSION_TTL_MS) || 10 * 60 * 1000;
const DOLLAR_CENTS = 100;
const MAX_PRICE_CENTS = 1_000_000 * DOLLAR_CENTS;

type SessionStatus =
  | "ACTIVE"
  | "PAYMENT_PENDING"
  | "COMPLETED"
  | "EXPIRED"
  | "FAILED";

type Listing = {
  id: string;
  eventName: string;
  date: string;
  price: number;
  available: number;
};

type CheckoutSession = {
  id: string;
  listingId: string;
  quantity: number;
  agreedPrice: number;
  priceAccepted: boolean;
  status: SessionStatus;
  userEmail: string;
  createdAt: number;
  expiresAt: number;
  orderId?: string;
};

type Order = {
  id: string;
  sessionId: string;
  total: number;
};

const listings = new Map<string, Listing>([
  [
    "listing-1",
    {
      id: "listing-1",
      eventName: "Dallas Concert",
      date: "2026-11-15",
      price: 120 * DOLLAR_CENTS,
      available: 20,
    },
  ],
]);

const sessions = new Map<string, CheckoutSession>();
const orders = new Map<string, Order>();
const listingTails = new Map<string, Promise<void>>();

function isWholeNumber(
  value: unknown,
  min: number,
  max: number,
): value is number {
  return (
    typeof value === "number" &&
    Number.isInteger(value) &&
    value >= min &&
    value <= max
  );
}

function isMoney(value: unknown): value is number {
  return isWholeNumber(value, 1, MAX_PRICE_CENTS);
}

function isInventory(value: unknown): value is number {
  return isWholeNumber(value, 0, 1_000_000);
}

function routeParam(value: string | string[] | undefined) {
  if (Array.isArray(value)) {
    return value[0] ?? "";
  }

  return value ?? "";
}

function normalizeEmail(value: unknown) {
  if (typeof value !== "string") {
    return null;
  }

  const email = value.trim().toLowerCase();

  if (!email.includes("@") || email.length < 3) {
    return null;
  }

  return email;
}

function isOpen(session: CheckoutSession) {
  return session.status === "ACTIVE" || session.status === "PAYMENT_PENDING";
}

function expireIfNeeded(session: CheckoutSession) {
  if (Date.now() < session.expiresAt || !isOpen(session)) {
    return;
  }

  session.status = session.status === "ACTIVE" ? "EXPIRED" : "FAILED";
}

function getSession(id: string) {
  const session = sessions.get(id);

  if (session) {
    expireIfNeeded(session);
  }

  return session;
}

function heldByOtherSessions(listingId: string, exceptSessionId?: string) {
  let held = 0;

  for (const session of sessions.values()) {
    expireIfNeeded(session);

    if (
      isOpen(session) &&
      session.listingId === listingId &&
      session.id !== exceptSessionId
    ) {
      held += session.quantity;
    }
  }

  return held;
}

function presentListing(listing: Listing, exceptSessionId?: string) {
  const held = heldByOtherSessions(listing.id, exceptSessionId);

  return {
    ...listing,
    held,
    purchasable: Math.max(0, listing.available - held),
  };
}

function presentCheckout(session: CheckoutSession, listing: Listing) {
  return {
    session,
    listing: presentListing(listing, session.id),
  };
}

function findOpenSession(userEmail: string, listingId: string) {
  for (const session of sessions.values()) {
    expireIfNeeded(session);

    if (
      session.userEmail === userEmail &&
      session.listingId === listingId &&
      isOpen(session)
    ) {
      return session;
    }
  }

  return null;
}

function commitOrder(session: CheckoutSession, listing: Listing) {
  const order: Order = {
    id: randomUUID(),
    sessionId: session.id,
    total: session.agreedPrice * session.quantity,
  };

  orders.set(order.id, order);
  listing.available -= session.quantity;
  session.orderId = order.id;
  session.status = "COMPLETED";

  return order;
}

function withListingLock(listingId: string, work: () => void) {
  const previous = listingTails.get(listingId) ?? Promise.resolve();
  const run = previous.then(() => {
    work();
  });

  listingTails.set(
    listingId,
    run.then(
      () => undefined,
      () => undefined,
    ),
  );

  return run;
}

function fail(
  res: Response,
  status: number,
  error: string,
  fields?: Record<string, unknown>,
) {
  res.status(status).json(fields ? { error, ...fields } : { error });
}

function requireDemoUser(req: Request, res: Response) {
  const userEmail = normalizeEmail(req.header("x-demo-email"));

  if (!userEmail) {
    fail(res, 401, "UNAUTHENTICATED");
    return null;
  }

  return userEmail;
}

function requireOwnedSession(req: Request, res: Response) {
  const userEmail = requireDemoUser(req, res);

  if (!userEmail) {
    return null;
  }

  const session = getSession(routeParam(req.params.id));

  if (!session) {
    fail(res, 404, "SESSION_NOT_FOUND");
    return null;
  }

  if (session.userEmail !== userEmail) {
    fail(res, 403, "SESSION_FORBIDDEN");
    return null;
  }

  return session;
}

function requireListing(res: Response, listingId: string, missingStatus: 404 | 500) {
  const listing = listings.get(listingId);

  if (!listing) {
    fail(
      res,
      missingStatus,
      missingStatus === 404 ? "LISTING_NOT_FOUND" : "LISTING_MISSING",
    );
    return null;
  }

  return listing;
}

function requireOpen(res: Response, session: CheckoutSession) {
  if (isOpen(session)) {
    return true;
  }

  fail(res, 409, "SESSION_NOT_ACTIVE", { status: session.status });
  return false;
}

function withOwnedSession(
  req: Request,
  res: Response,
  work: (session: CheckoutSession) => void | Promise<void>,
) {
  const session = requireOwnedSession(req, res);

  if (session) {
    return work(session);
  }
}

function withLockedSession(
  req: Request,
  res: Response,
  work: (session: CheckoutSession) => void,
) {
  return withOwnedSession(req, res, (session) =>
    withListingLock(session.listingId, () => {
      expireIfNeeded(session);
      work(session);
    }),
  );
}

function updateListing(
  req: Request,
  res: Response,
  value: unknown,
  valid: (value: unknown) => value is number,
  invalidError: string,
  apply: (listing: Listing, value: number) => void,
) {
  if (!requireDemoUser(req, res)) {
    return;
  }

  const listing = requireListing(res, routeParam(req.params.id), 404);

  if (!listing) {
    return;
  }

  if (!valid(value)) {
    fail(res, 400, invalidError);
    return;
  }

  return withListingLock(listing.id, () => {
    apply(listing, value);
    res.json({ listing: presentListing(listing) });
  });
}

app.get("/api/checkout-sessions", (req, res) => {
  const userEmail = requireDemoUser(req, res);

  if (!userEmail) {
    return;
  }

  const matchingSessions = [...sessions.values()]
    .filter((session) => session.userEmail === userEmail)
    .flatMap((session) => {
      expireIfNeeded(session);

      const listing = listings.get(session.listingId);

      if (!listing) {
        return [];
      }

      return [presentCheckout(session, listing)];
    })
    .sort((a, b) => b.session.createdAt - a.session.createdAt);

  res.json({ sessions: matchingSessions });
});

app.post("/api/checkout-sessions", (req, res) => {
  const userEmail = requireDemoUser(req, res);

  if (!userEmail) {
    return;
  }

  const { listingId, quantity = 1 } = req.body ?? {};

  if (
    typeof listingId !== "string" ||
    !Number.isInteger(quantity) ||
    quantity < 1
  ) {
    fail(res, 400, "INVALID_CHECKOUT_INPUT");
    return;
  }

  return withListingLock(listingId, () => {
    const listing = requireListing(res, listingId, 404);

    if (!listing) {
      return;
    }

    const openSession = findOpenSession(userEmail, listingId);

    if (openSession) {
      fail(res, 409, "CHECKOUT_ALREADY_OPEN", { sessionId: openSession.id });
      return;
    }

    const available = presentListing(listing).purchasable;

    if (available < quantity) {
      fail(res, 409, "INVENTORY_UNAVAILABLE", { available });
      return;
    }

    const now = Date.now();

    const session: CheckoutSession = {
      id: randomUUID(),
      listingId,
      quantity,
      agreedPrice: listing.price,
      priceAccepted: true,
      status: "ACTIVE",
      userEmail,
      createdAt: now,
      expiresAt: now + SESSION_TTL_MS,
    };

    sessions.set(session.id, session);
    res.status(201).json(presentCheckout(session, listing));
  });
});

app.get("/api/checkout-sessions/:id", (req, res) =>
  withOwnedSession(req, res, (session) => {
    const listing = requireListing(res, session.listingId, 500);

    if (!listing) {
      return;
    }

    res.json({
      ...presentCheckout(session, listing),
      currentPrice: listing.price,
    });
  }),
);

app.post("/api/checkout-sessions/:id/accept-price", (req, res) =>
  withLockedSession(req, res, (session) => {
    if (!requireOpen(res, session)) {
      return;
    }

    const expectedPrice = req.body?.expectedPrice;

    if (!isMoney(expectedPrice)) {
      fail(res, 400, "INVALID_PRICE");
      return;
    }

    const listing = requireListing(res, session.listingId, 500);

    if (!listing) {
      return;
    }

    if (listing.price !== expectedPrice) {
      fail(res, 409, "PRICE_CHANGED", { currentPrice: listing.price });
      return;
    }

    session.agreedPrice = listing.price;
    session.priceAccepted = true;

    res.json({
      session,
      currentPrice: listing.price,
    });
  }),
);

app.post("/api/checkout-sessions/:id/complete", (req, res) =>
  withLockedSession(req, res, (session) => {
    if (session.status === "COMPLETED" && session.orderId) {
      const order = orders.get(session.orderId);

      if (!order) {
        fail(res, 500, "ORDER_MISSING");
        return;
      }

      res.json({ session, order });
      return;
    }

    if (!requireOpen(res, session)) {
      return;
    }

    const simulateFailure = req.body?.simulatePaymentFailure === true;
    const simulatePending = req.body?.simulatePaymentPending === true;

    if (simulateFailure) {
      const retryable = session.status === "ACTIVE";

      if (session.status === "PAYMENT_PENDING") {
        session.status = "FAILED";
      }

      res.status(402).json({
        error: "PAYMENT_FAILED",
        retryable,
        session,
      });
      return;
    }

    if (simulatePending && session.status === "PAYMENT_PENDING") {
      res.status(202).json({ session });
      return;
    }

    const listing = requireListing(res, session.listingId, 500);

    if (!listing) {
      return;
    }

    const available = presentListing(listing, session.id).purchasable;

    if (available < session.quantity) {
      fail(res, 409, "INVENTORY_UNAVAILABLE", { available });
      return;
    }

    if (!session.priceAccepted || session.agreedPrice !== listing.price) {
      session.priceAccepted = false;
      fail(res, 409, "PRICE_CHANGED", { currentPrice: listing.price });
      return;
    }

    if (simulatePending) {
      session.status = "PAYMENT_PENDING";
      res.status(202).json({ session });
      return;
    }

    res.status(201).json({
      session,
      order: commitOrder(session, listing),
    });
  }),
);

app.patch("/api/dev/listings/:id/price", (req, res) =>
  updateListing(req, res, req.body?.price, isMoney, "INVALID_PRICE", (listing, price) => {
    listing.price = price;
  }),
);

app.patch("/api/dev/listings/:id/inventory", (req, res) =>
  updateListing(
    req,
    res,
    req.body?.available,
    isInventory,
    "INVALID_INVENTORY",
    (listing, available) => {
      listing.available = available;
    },
  ),
);

app.post("/api/dev/sessions/:id/expire", (req, res) =>
  withOwnedSession(req, res, (session) => {
    if (isOpen(session)) {
      session.status = "EXPIRED";
    }

    res.json({ session });
  }),
);

app.get("/api/listings/:id", (req, res) => {
  const listing = requireListing(res, routeParam(req.params.id), 404);

  if (!listing) {
    return;
  }

  res.json({ listing: presentListing(listing) });
});

app.use((_req, res) => {
  fail(res, 404, "NOT_FOUND");
});

app.use((err: unknown, _req: Request, res: Response, _next: NextFunction) => {
  if (
    err instanceof SyntaxError &&
    "status" in err &&
    (err as { status?: number }).status === 400
  ) {
    fail(res, 400, "INVALID_JSON");
    return;
  }

  console.error(err);

  if (!res.headersSent) {
    fail(res, 500, "INTERNAL_ERROR");
  }
});

app.listen(PORT, () => {
  console.log(`Checkout server running at http://localhost:${PORT}`);
});
